import * as _smthrs_db_adapter from '@smthrs/db/adapter';

/**
 * Opportunistically reclaim detached stdout/stderr logs in the managed
 * `.smithers/logs` directory. Active/nonterminal runs are always protected.
 * A DB-absent log is protected until it crosses the retention window.
 *
 * The optional seams keep filesystem behavior and environment limits
 * deterministic in tests. Passing `logDir` changes only the directory this
 * invocation manages; CLI `--log-dir` overrides are deliberately not fed here
 * because operator-owned directories must retain their existing semantics.
 *
 * @param {{
 *   cwd?: string;
 *   logDir?: string;
 *   adapter?: Pick<import("@smthrs/db/adapter").SmithersDb, "getRun"> | null;
 *   env?: NodeJS.ProcessEnv;
 *   nowMs?: number;
 *   olderThanMs?: number;
 *   dryRun?: boolean;
 *   allowAbsentRuns?: boolean;
 *   minimumAgeForSizeCap?: boolean;
 *   warn?: (line: string) => void;
 * }} [options]
 */
declare function reapDetachedRunLogs(options?: {
    cwd?: string;
    logDir?: string;
    adapter?: Pick<_smthrs_db_adapter.SmithersDb, "getRun"> | null;
    env?: NodeJS.ProcessEnv;
    nowMs?: number;
    olderThanMs?: number;
    dryRun?: boolean;
    allowAbsentRuns?: boolean;
    minimumAgeForSizeCap?: boolean;
    warn?: (line: string) => void;
}): Promise<{
    removed: any[];
    bytesFreed: number;
    totalBytes: number;
    logDir: string;
    dryRun: boolean;
}>;

export { reapDetachedRunLogs };
